import{_ as l,a0 as p,w as d,s as r,ao as t,I as n,x as e,a1 as o,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"有所為，有所不為：在 Linux 中使用超級用户權限 | LCTT x X-CMD","titleTemplate":false,"description":"有所為，有所不為：在 Linux 中使用超級用户權限 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"有所為，有所不為：在 Linux 中使用超級用户權限 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"有所為，有所不為：在 Linux 中使用超級用户權限 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181126 How to use the sudo command to deploy superuser powers on Linux","title":"有所為，有所不為：在 Linux 中使用超級用户權限","tag":"201812","desc":""},"relativePath":"201812/20181126 How to use the sudo command to deploy superuser powers on Linux.md","filePath":"[post].md"}'),u={name:"201812/20181126 How to use the sudo command to deploy superuser powers on Linux.md"};function h(c,s,g,k,b,m){const a=p("Link");return d(),r("div",null,[s[18]||(s[18]=t(`<h1 id="有所為-有所不為-在-linux-中使用超級用户權限" tabindex="-1">有所為，有所不為：在 Linux 中使用超級用户權限 <a class="header-anchor" href="#有所為-有所不為-在-linux-中使用超級用户權限" aria-label="Permalink to “有所為，有所不為：在 Linux 中使用超級用户權限”">​</a></h1><blockquote><p>sudo 命令允許特權用户以 root 用户身份運行全部或部分命令，但是理解其能做什麼和不能做什麼很有幫助。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2018/11/superman-100781085-large.jpg" alt=""></p><p>在你想要使用超級權限臨時運行一條命令時，<code>sudo</code> 命令非常方便，但是當它不能如你期望的工作時，你也會遇到一些麻煩。比如説你想在某些日誌文件結尾添加一些重要的信息，你可能會嘗試這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Important note&quot; &gt;&gt; /var/log/somelog</span></span>
<span class="line"><span>-bash: /var/log/somelog: Permission denied</span></span></code></pre></div><p>好吧，看起來你似乎需要一些額外的特權。一般來説，你不能使用你的用户賬號向系統日誌中寫入東西。我們使用 <code>sudo</code> 再嘗試一次吧。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo !!</span></span>
<span class="line"><span>sudo echo &quot;Important note&quot; &gt;&gt; /var/log/somelog</span></span>
<span class="line"><span>-bash: /var/log/somelog: Permission denied</span></span></code></pre></div><p>嗯，它還是沒有啥反應。我們來試點不同的吧。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo &#39;echo &quot;Important note&quot; &gt;&gt; /var/log/somelog&#39;</span></span>
<span class="line"><span>sudo: echo &quot;Important note&quot; &gt;&gt; /var/log/somelog: command not found</span></span></code></pre></div>`,9)),n("p",null,[s[1]||(s[1]=e("也可以查看：",-1)),o(a,{href:"https://www.networkworld.com/article/3242170/linux/invaluable-tips-and-tricks-for-troubleshooting-linux.html"},{default:i(()=>[...s[0]||(s[0]=[e("在 Linux 下排查故障的寶貴提示和技巧",-1)])]),_:1}),s[2]||(s[2]=e("。",-1))]),s[19]||(s[19]=t(`<h3 id="接下來該幹什麼" tabindex="-1">接下來該幹什麼？ <a class="header-anchor" href="#接下來該幹什麼" aria-label="Permalink to “接下來該幹什麼？”">​</a></h3><p>上面在執行完第一條命令後的回應顯示，我們缺少向日志文件寫入時必須的特權。第二次，我們使用 root 權限運行了第一次的命令，但是返回了一個“沒有權限”的錯誤。第三次，我們把整個命令放在一個引號裏面再運行了一遍，返回了一個“沒有發現命令”的錯誤。所以，到底錯在哪裏了呢？</p><ul><li>第一條命令：沒有 root 特權，你無法向這個日誌中寫入東西。</li><li>第二條命令：你的超級權限沒有延伸到重定向。</li><li>第三條命令：<code>sudo</code> 不理解你用引號括起來的整個 “命令”。</li></ul><p>而且如果你的用户還未添加到 sudo 用户組的時候，如果嘗試使用 <code>sudo</code>，你可能已經看到過像下面的這麼一條錯誤了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nemo is not in the sudoers file. This incident will be reported.</span></span></code></pre></div><h3 id="你可以做什麼" tabindex="-1">你可以做什麼？ <a class="header-anchor" href="#你可以做什麼" aria-label="Permalink to “你可以做什麼？”">​</a></h3><p>一個相當簡單的選擇就是使用 <code>sudo</code> 命令暫時成為 root。鑑於你已經有了 sudo 特權，你可以使用下面的命令執行此操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo su</span></span>
<span class="line"><span>[sudo] password for nemo:</span></span>
<span class="line"><span>#</span></span></code></pre></div><p>注意這個改變的提示符表明了你的新身份。然後你就可以以 root 運行之前的命令了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo &quot;Important note&quot; &gt;&gt; /var/log/somelog</span></span></code></pre></div><p>接着你可以輸入 <code>^d</code> 返回你之前的身份。當然了，一些 sudo 的配置可能會阻止你使用 <code>sudo</code> 命令成為 root。</p><p>另一個切換用户為 root 的方法是僅用 <code>su</code> 命令，但是這需要你知道 root 密碼。許多人被賦予了訪問 sudo 的權限，而並不知道 root 密碼，所以這並不是總是可行。</p><p>（採用 su 直接）切換到 root 之後，你就可以以 root 的身份運行任何你想執行的命令了。這種方式的問題是：1) 每個想要使用 root 特權的人都需要事先知道 root 的密碼（這樣不很安全）；2) 如果在運行需要 root 權限的特定命令後未能退出特權狀態，你的系統可能會受到一些重大錯誤的波及。<code>sudo</code> 命令旨在允許您僅在真正需要時使用 root 權限，並控制每個 sudo 用户應具有的 root 權限。它也可以使你在使用完 root 特權之後輕鬆地回到普通用户的狀態。</p><p>另外請注意，整個討論的前提是你可以正常地訪問 sudo，並且你的訪問權限沒有受限。詳細的內容後面會介紹到。</p><p>還有一個選擇就是使用一個不同的命令。如果通過編輯文件從而在其後添加內容是一種選擇的話，你也許可以使用 <code>sudo vi /var/log/somelog</code>，雖然編輯一個活躍的日誌文件通常不是一個好主意，因為系統可能會頻繁的向這個文件中進行寫入操作。</p><p>最後一個但是有點複雜的選擇是，使用下列命令之一可以解決我們之前看到的問題，但是它們涉及到了很多複雜的語法。第一個命令允許你在得到 “沒有權限” 的拒絕之後可以使用 <code>!!</code> 重複你的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo echo &quot;Important note&quot; &gt;&gt; /var/log/somelog</span></span>
<span class="line"><span>-bash: /var/log/somelog: Permission denied</span></span>
<span class="line"><span>$ !!:gs/&gt;/|sudo tee -a /    &lt;=====</span></span>
<span class="line"><span>$ tail -1 /var/log/somelog</span></span>
<span class="line"><span>Important note</span></span></code></pre></div><p>第二種是通過 <code>sudo</code> 命令，把你想要添加的信息傳遞給 <code>tee</code>。注意，<code>-a</code> 指定了你要<strong>附加</strong>文本到目標文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Important note&quot; | sudo tee -a /var/log/somelog</span></span>
<span class="line"><span>$ tail -1 /var/log/somelog</span></span>
<span class="line"><span>Important note</span></span></code></pre></div><h3 id="sudo-有多可控" tabindex="-1">sudo 有多可控？ <a class="header-anchor" href="#sudo-有多可控" aria-label="Permalink to “sudo 有多可控？”">​</a></h3><p>回答這個問題最快速的回答就是，它取決於管理它的人。大多數 Linux 的默認設置都非常簡單。如果一個用户被安排到了一個特別的組中，例如 <code>wheel</code> 或者 <code>admin</code> 組，那這個用户無需知道 root 的密碼就可以擁有運行任何命令的能力。這就是大多數 Linux 系統中的默認設置。一旦在 <code>/etc/group</code> 中添加了一個用户到了特權組中，這個用户就可以以 root 的權力運行任何命令。另一方面，可以配置 sudo，以便一些用户只能夠以 root 身份運行單一指令或者一組命令中的任何一個。</p><p>如果把像下面展示的這些行添加到了 <code>/etc/sudoers</code> 文件中，例如 “nemo” 這個用户可以以 root 身份運行 <code>whoami</code> 命令。在現實中，這可能不會造成任何影響，它非常適合作為一個例子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># User alias specification</span></span>
<span class="line"><span>nemo ALL=(root) NOPASSWD: WHOAMI</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Cmnd alias specification</span></span>
<span class="line"><span>Cmnd_Alias WHOAMI = /usr/bin/whoami</span></span></code></pre></div><p>注意，我們添加了一個命令別名（<code>Cmnd_Alias</code>），它指定了一個可以運行的命令的全路徑，以及一個用户別名，允許這個用户無需密碼就可以使用 <code>sudo</code> 執行的單個命令。</p><p>當 nemo 運行 <code>sudo whoami</code> 命令的時候，他將會看到這個：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo whoami</span></span>
<span class="line"><span>root</span></span></code></pre></div><p>注意這個，因為 nemo 使用 <code>sudo</code> 執行了這條命令，<code>whoami</code> 會顯示該命令運行時的用户是 <code>root</code>。</p><p>至於其他的命令，nemo 將會看到像這樣的一些內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo date</span></span>
<span class="line"><span>[sudo] password for nemo:</span></span>
<span class="line"><span>Sorry, user nemo is not allowed to execute &#39;/bin/date&#39; as root on butterfly.</span></span></code></pre></div><h3 id="sudo-的默認設置" tabindex="-1">sudo 的默認設置 <a class="header-anchor" href="#sudo-的默認設置" aria-label="Permalink to “sudo 的默認設置”">​</a></h3><p>在默認路徑中，我們會利用像下面展示的 <code>/etc/sudoers</code> 文件中的幾行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo egrep &quot;admin|sudo&quot; /etc/sudoers</span></span>
<span class="line"><span># Members of the admin group may gain root privileges</span></span>
<span class="line"><span>%admin ALL=(ALL) ALL        &lt;=====</span></span>
<span class="line"><span># Allow members of group sudo to execute any command</span></span>
<span class="line"><span>%sudo ALL=(ALL:ALL) ALL     &lt;=====</span></span></code></pre></div><p>在這幾行中，<code>%admin</code> 和 <code>%sudo</code> 都説明了任何添加到這些組中的人都可以使用 <code>sudo</code> 命令以 root 的身份運行任何命令。</p><p>下面列出的是 <code>/etc/group</code> 中的一行，它意味着每一個在該組中列出的成員，都擁有了 sudo 特權，而無需在 <code>/etc/sudoers</code> 中進行任何修改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo:x:27:shs,nemo</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p><code>sudo</code> 命令意味着你可以根據需要輕鬆地部署超級用户的訪問權限，而且只有在需要的時候才能賦予用户非常有限的特權訪問權限。你可能會遇到一些與簡單的 <code>sudo command</code> 不同的問題，不過在 <code>sudo</code> 的回應中應該會顯示你遇到了什麼問題。</p><hr>`,38)),n("p",null,[s[4]||(s[4]=e("via: ",-1)),o(a,{href:"https://www.networkworld.com/article/3322504/linux/selectively-deploying-your-superpowers-on-linux.html"},{default:i(()=>[...s[3]||(s[3]=[e("https://www.networkworld.com/article/3322504/linux/selectively-deploying-your-superpowers-on-linux.html",-1)])]),_:1})]),n("p",null,[s[9]||(s[9]=e("作者：",-1)),o(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[5]||(s[5]=[e("Sandra Henry-Stocker",-1)])]),_:1}),s[10]||(s[10]=e(" 選題：",-1)),o(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 譯者：",-1)),o(a,{href:"https://github.com/dianbanjiu"},{default:i(()=>[...s[7]||(s[7]=[e("dianbanjiu",-1)])]),_:1}),s[12]||(s[12]=e(" 校對：",-1)),o(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=e("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原創編譯，",-1)),o(a,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[e("Linux中國",-1)])]),_:1}),s[17]||(s[17]=e(" 榮譽推出",-1))])])}const v=l(u,[["render",h]]);export{y as __pageData,v as default};
